insert into public.site_content (id, page, label, data, visible)
values
  ('home.hero', 'Beranda', 'Sambutan utama', '{"eyebrow":"Tundungan, Krian · Sidoarjo","title":"Berakar pada adab. Bertumbuh dengan ilmu.","description":"Pendidikan sekolah dan pesantren dalam satu lingkungan. Bersama Al-Huda, membimbing putra-putri Anda menjadi pribadi yang berilmu, berakhlak, dan mandiri.","primaryAction":"Mengenal Al-Huda","secondaryAction":"Hubungi sekretariat","footnote":"Yayasan Pendidikan Islam Al-Huda Tundungan","supportingLine":"Sekolah & pesantren · Satu lingkungan pendidikan"}'::jsonb, true),
  ('home.units', 'Beranda', 'Pilihan lembaga', '{"eyebrow":"Lembaga pendidikan","title":"Dua jalan belajar. Satu bekal kehidupan.","description":"Pendidikan formal dan tradisi pesantren yang saling melengkapi.","smpCaption":"Sekolah menengah pertama","smpTitle":"SMP Al-Huda Krian","smpDescription":"Kurikulum Merdeka, penguatan sains dan bahasa, serta pembiasaan ibadah dalam keseharian.","smpDetail":"Profil, kurikulum & kehidupan sekolah","pondokCaption":"Pondok pesantren","pondokTitle":"Pesantren Al-Huda","pondokDescription":"Tahfidz Al-Qur’an, kajian kitab kuning, dan pembinaan adab melalui kehidupan bersama di pesantren.","pondokDetail":"Program, asatidz & keseharian santri"}'::jsonb, true),
  ('home.foundation', 'Beranda', 'Tentang yayasan', '{"eyebrow":"Mengenal yayasan","title":"Ilmu yang dipelajari. Adab yang dijalani.","paragraphOne":"Al-Huda tumbuh dari ikhtiar para alim ulama dan masyarakat Krian untuk menghadirkan pendidikan Islam yang dekat dengan kehidupan. Keilmuan modern berjalan bersama tradisi kepesantrenan Ahlussunnah wal Jama’ah.","paragraphTwo":"Di sekolah maupun di pondok, proses belajar mencakup pengetahuan, kebiasaan beribadah, dan tanggung jawab kepada sesama.","linkLabel":"Sejarah, visi & struktur yayasan"}'::jsonb, true),
  ('home.news', 'Beranda', 'Buletin berita', '{"eyebrow":"Buletin Al-Huda","title":"Kabar dari lingkungan kita","allNewsLabel":"Semua berita & arsip","emptyMessage":"Belum ada berita dari lembaga ini. Silakan pilih lembaga lainnya."}'::jsonb, true),
  ('home.agenda', 'Beranda', 'Agenda', '{"eyebrow":"Catat tanggalnya","title":"Agenda bersama","description":"Jadwal akademik, kegiatan santri, dan pertemuan keluarga besar Al-Huda.","items":[{"id":"ag-2","title":"Peringatan Maulid Nabi Muhammad SAW & Sholawat Bersama","date":"2026-09-04","time":"19.30 WIB - Selesai","location":"Masjid Jami'' Al-Huda Tundungan","unit":"pondok","category":"Keagamaan","description":"Kajian sirah nabawiyah dan pembacaan Simtudduror bersama grup hadrah santri.","endDate":""},{"id":"ag-3","title":"Asesmen Sumatif Tengah Semester Ganjil SMP Al-Huda","date":"2026-09-15","endDate":"2026-09-22","time":"07.00 - 13.00 WIB","location":"Ruang Kelas SMP Al-Huda","unit":"smp","category":"Akademik","description":"Evaluasi capaian pembelajaran Kurikulum Merdeka berbasis digital exam."},{"id":"ag-4","title":"Perkemahan Santri dan Pramuka Terpadu (PERSADA)","date":"2026-10-02","endDate":"2026-10-04","time":"3 Hari 2 Malam","location":"Bumi Perkemahan Claket, Pacet","unit":"yayasan","category":"Kesiswaan","description":"Kegiatan kepramukaan gabungan untuk melatih kemandirian, kepemimpinan, dan ukhuwah."}]}'::jsonb, true),
  ('layout.home', 'Beranda', 'Urutan bagian halaman', '{"items":[{"id":"home.hero","title":"Sambutan utama"},{"id":"home.units","title":"Pilihan lembaga"},{"id":"home.foundation","title":"Tentang yayasan"},{"id":"home.news","title":"Buletin berita"},{"id":"home.agenda","title":"Agenda"}]}'::jsonb, true),
  ('news.page', 'Berita & pengumuman', 'Judul dan pengantar', '{"eyebrow":"Warta & pengumuman","title":"Berita, Artikel & Prestasi","description":"Kumpulan informasi resmi kegiatan Yayasan Al-Huda Tundungan, prestasi SMP Al-Huda, dan kabar santri Pondok Pesantren Al-Huda Krian.","searchPlaceholder":"Cari judul berita atau topik...","categoryLabel":"Kategori","allCategoriesLabel":"Semua kategori","emptyTitle":"Tidak Ada Berita Ditemukan","emptyDescription":"Belum ada artikel atau berita yang sesuai dengan kriteria pencarian dan filter Anda saat ini.","backLabel":"Kembali ke Daftar Berita","shareLabel":"Bagikan Berita"}'::jsonb, true),
  ('gallery.page', 'Galeri', 'Judul dan pengantar', '{"eyebrow":"Dokumentasi & media","title":"Galeri Kegiatan & Fasilitas","description":"Dokumentasi foto dan video kegiatan belajar mengajar, peribadatan santri, sarana prasarana, dan prestasi santri/siswa Al-Huda.","categoryLabel":"Kategori","allCategoriesLabel":"Semua kategori","emptyTitle":"Galeri Media Belum Tersedia","emptyDescription":"Belum ada foto atau video untuk kategori ini. Silakan pilih kategori lainnya."}'::jsonb, true),
  ('smp.staff.page', 'Profil SMP', 'Judul guru dan staf', '{"eyebrow":"Tenaga pendidik & kependidikan","title":"Dewan Guru & Staff SMP Al-Huda","description":"Dididik oleh para pendidik profesional, bersertifikasi, berdedikasi tinggi, dan berintegritas islami.","allStaffLabel":"Semua Guru & Staff","leadershipLabel":"Pimpinan Sekolah","teacherLabel":"Guru Mata Pelajaran","staffLabel":"Staff TU & IT","searchPlaceholder":"Cari nama guru atau mata pelajaran..."}'::jsonb, true),
  ('pondok.staff.page', 'Profil pesantren', 'Judul asatidz', '{"eyebrow":"Dewan asatidz & masyayikh","title":"Pengasuh & Dewan Asatidz Pondok Pesantren","description":"Diasuh langsung oleh para kyai, huffadz bersanad, dan asatidz alumni pondok pesantren salaf terkemuka.","allStaffLabel":"Semua Asatidz","leadershipLabel":"Dewan Pengasuh","teacherLabel":"Ustadz Diniyah & Tahfidz","staffLabel":"Pengurus Asrama","searchPlaceholder":"Cari nama asatidz atau bidang keilmuan..."}'::jsonb, true),
  ('about.hero', 'Tentang yayasan', 'Judul halaman', '{"eyebrow":"Profil kelembagaan","title":"Tentang Yayasan Al-Huda Tundungan","description":"Menelusuri sejarah, visi-misi, nilai-nilai dasar, dan struktur kepengurusan terpadu di Krian, Sidoarjo."}'::jsonb, true),
  ('about.history', 'Tentang yayasan', 'Sejarah dan identitas', '{"title":"Sejarah Singkat Yayasan","subtitle":"Informasi kelembagaan","paragraphOne":"Yayasan Pendidikan Islam Al-Huda Tundungan didirikan pada tahun 1994 oleh para kyai dan tokoh masyarakat di Dusun Tundungan, Kecamatan Krian, Kabupaten Sidoarjo. Berawal dari majelis taklim dan pengajian kitab kuning, yayasan berkembang dengan mendirikan SMP Al-Huda dan unit kepesantrenan terpadu.","paragraphTwo":"Yayasan Al-Huda terus mengembangkan sarana pendidikan dan memperkuat kurikulum terintegrasi antara kurikulum nasional dan kepesantrenan salafiyah Ahlussunnah wal Jama’ah.","legalLabel":"Landasan hukum","legal":"SK Kemenkumham RI & Akta Notaris Resmi Yayasan","regionLabel":"Wilayah khidmah","region":"Tundungan, Krian, Sidoarjo - Jawa Timur","affiliationLabel":"Afiliasi keagamaan","affiliation":"Ahlussunnah wal Jama’ah An-Nahdliyyah"}'::jsonb, true),
  ('about.vision', 'Tentang yayasan', 'Visi dan misi', '{"visionTitle":"Visi Yayasan","missionTitle":"Misi Yayasan","vision":"Terwujudnya lembaga pendidikan Islam yang unggul, mencetak generasi yang berakhlaqul karimah, berilmu amaliyah, beramal ilmiah, serta berdaya saing global.","missionOne":"Menyelenggarakan pendidikan formal SMP dan pesantren yang berkualitas dan berkarakter.","missionTwo":"Membina tradisi keilmuan Islam, tahfidzul Qur’an, dan penguasaan bahasa asing.","missionThree":"Menanamkan nilai-nilai adab, kemandirian santri, dan kepedulian sosial kemasyarakatan."}'::jsonb, true),
  ('about.organization', 'Tentang yayasan', 'Struktur pengurus', '{"eyebrow":"Bagan struktur organisasi","title":"Struktur Pengurus Yayasan & Unit","description":"Hierarki kepengurusan yang menghubungkan Dewan Pembina, Pengurus Harian Yayasan, Pimpinan SMP Al-Huda, dan Pengasuh Pondok Pesantren.","items":[{"id":"org-root","name":"Dewan Pembina Yayasan Al-Huda","role":"Pembina Yayasan","level":"1","unit":"yayasan","photoUrl":"","parentId":""},{"id":"org-pengawas","name":"Dewan Pengawas Yayasan","role":"Pengawas","level":"1","unit":"yayasan","photoUrl":"","parentId":"org-root"},{"id":"org-ketua","name":"KH. Ahmad Dahlan Thohir, M.Pd.I","role":"Ketua Umum Yayasan","level":"2","unit":"yayasan","photoUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?q=80&w=200&auto=format&fit=crop","parentId":"org-root"},{"id":"org-sekretaris","name":"H. Mochammad Syarifuddin, S.E., M.M.","role":"Sekretaris Yayasan","level":"3","unit":"yayasan","photoUrl":"","parentId":"org-ketua"},{"id":"org-bendahara","name":"Hj. Siti Mahmudah, S.Pd.","role":"Bendahara Yayasan","level":"3","unit":"yayasan","photoUrl":"","parentId":"org-ketua"},{"id":"org-smp","name":"Drs. H. Abdul Ghofur, M.Si.","role":"Kepala SMP Al-Huda","level":"3","unit":"smp","photoUrl":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?q=80&w=200&auto=format&fit=crop","parentId":"org-ketua"},{"id":"org-smp-kurikulum","name":"Nurul Hidayati, S.Pd., Gr.","role":"Waka Kurikulum SMP","level":"4","unit":"smp","photoUrl":"","parentId":"org-smp"},{"id":"org-smp-kesiswaan","name":"M. Ali Ridho, S.Pd.","role":"Waka Kesiswaan SMP","level":"4","unit":"smp","photoUrl":"","parentId":"org-smp"},{"id":"org-smp-sarpras","name":"Ahmad Zaini, S.Pd.","role":"Waka Sarpras & Humas","level":"4","unit":"smp","photoUrl":"","parentId":"org-smp"},{"id":"org-pondok","name":"Kyai Muhyiddin Al-Hafidz","role":"Pengasuh Pondok Pesantren Al-Huda","level":"3","unit":"pondok","photoUrl":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?q=80&w=200&auto=format&fit=crop","parentId":"org-ketua"},{"id":"org-pondok-lurah","name":"Ustadz Farid Muhaimin, Lc., M.H.","role":"Lurah Pondok & Diniyah","level":"4","unit":"pondok","photoUrl":"","parentId":"org-pondok"},{"id":"org-pondok-tahfidz","name":"Ustadzah Hj. Fatimatuz Zahro","role":"Koordinator Tahfidz","level":"4","unit":"pondok","photoUrl":"","parentId":"org-pondok"},{"id":"org-pondok-keamanan","name":"Ustadz Muhammad Ilham, S.Pd.I","role":"Kamtib & Keasramaan","level":"4","unit":"pondok","photoUrl":"","parentId":"org-pondok"}]}'::jsonb, true),
  ('layout.about', 'Tentang yayasan', 'Urutan bagian halaman', '{"items":[{"id":"about.hero","title":"Judul halaman"},{"id":"about.history","title":"Sejarah dan identitas"},{"id":"about.vision","title":"Visi dan misi"},{"id":"about.organization","title":"Struktur pengurus"}]}'::jsonb, true),
  ('smp.hero', 'Profil SMP', 'Sambutan SMP', '{"eyebrow":"Sekolah Menengah Pertama","title":"SMP Al-Huda Tundungan","description":"Membentuk pelajar beradab, berprestasi, dan siap menghadapi perubahan zaman."}'::jsonb, true),
  ('smp.history', 'Profil SMP', 'Identitas dan keunggulan', '{"title":"Sejarah Singkat SMP Al-Huda","subtitle":"Identitas dan keunggulan sekolah","paragraphOne":"SMP Al-Huda didirikan di bawah naungan Yayasan Pendidikan Islam Al-Huda Tundungan untuk menjawab kebutuhan masyarakat Krian Sidoarjo akan sekolah lanjutan yang unggul secara akademis dan membina akhlak.","paragraphTwo":"Dengan dukungan tenaga pendidik, SMP Al-Huda mendampingi siswa untuk melanjutkan pendidikan dan mengembangkan potensi mereka.","metricOne":"Akreditasi A","metricOneNote":"BAN-S/M Jatim","metricTwo":"NPSN Resmi","metricTwoNote":"Kemendikbudristek","metricThree":"12 Rombel","metricThreeNote":"Smart Classroom","metricFour":"100% Lulus","metricFourNote":"Prestasi Akademik"}'::jsonb, true),
  ('smp.vision', 'Profil SMP', 'Visi dan misi SMP', '{"visionTitle":"Visi SMP Al-Huda","missionTitle":"Misi SMP Al-Huda","vision":"Mewujudkan generasi pelajar yang unggul dalam ilmu pengetahuan dan teknologi, kokoh dalam iman dan taqwa, berakhlak mulia, serta peduli lingkungan.","missionOne":"Melaksanakan pembelajaran Kurikulum Merdeka yang inovatif, berdiferensiasi, dan berbasis teknologi digital.","missionTwo":"Membiasakan ibadah harian seperti sholat dhuha, sholat dhuhur berjamaah, dan tadarrus Juz 30.","missionThree":"Mengembangkan bakat siswa melalui bimbingan olimpiade sains, robotik, olahraga, dan seni islami."}'::jsonb, true),
  ('smp.curriculum', 'Profil SMP', 'Program pembelajaran', '{"eyebrow":"Struktur pembelajaran","title":"Kurikulum Integrasi Nasional & Kepesantrenan","description":"Perpaduan seimbang yang mempersiapkan siswa siap bersaing di era digital tanpa kehilangan adab islami.","cardOneTitle":"Kurikulum Merdeka Nasional","cardOneDescription":"Mata pelajaran nasional dengan Projek Penguatan Profil Pelajar Pancasila.","cardTwoTitle":"Muatan Kepesantrenan & Agama","cardTwoDescription":"Tahsin, tahfidz Al-Qur’an, fiqih ibadah, bahasa Arab, dan kajian akhlak.","cardThreeTitle":"Pengembangan IT & Bahasa","cardThreeDescription":"Praktikum komputer, coding dasar, kuis interaktif, dan percakapan bahasa."}'::jsonb, true),
  ('smp.cta', 'Profil SMP', 'Ajakan menghubungi', '{"title":"Ingin mengenal lebih jauh SMP Al-Huda?","description":"Sekretariat siap membantu menjawab pertanyaan tentang kegiatan dan program sekolah.","action":"Hubungi sekretariat"}'::jsonb, true),
  ('layout.smp-profile', 'Profil SMP', 'Urutan bagian halaman profil', '{"items":[{"id":"smp.hero","title":"Sambutan SMP"},{"id":"smp.history","title":"Identitas dan keunggulan"},{"id":"smp.vision","title":"Visi dan misi SMP"},{"id":"smp.curriculum","title":"Program pembelajaran"}]}'::jsonb, true),
  ('smp.facilities', 'Profil SMP', 'Halaman fasilitas SMP', '{"eyebrow":"Sarana & prasarana","title":"Fasilitas Penunjang SMP Al-Huda","description":"Ruang belajar, laboratorium, sarana olahraga, dan perpustakaan untuk mendukung kegiatan siswa.","itemNote":"Kondisi Prima & Terawat","locationLabel":"Kampus Krian","items":[{"id":"fac-smp-1","name":"Smart Classroom Ber-AC & Multimedia","description":"Ruang kelas yang nyaman dan representatif dengan proyektor interaktif, AC, dan tata letak ergonomis.","imageUrl":"https://images.unsplash.com/photo-1580582932707-520aed937b7b?q=80&w=800&auto=format&fit=crop"},{"id":"fac-smp-2","name":"Laboratorium Komputer & Bahasa","description":"Dilengkapi 36 unit komputer PC all-in-one terkoneksi fiber-optic internet untuk CBT dan pembelajaran koding.","imageUrl":"https://images.unsplash.com/photo-1562774053-701939374585?q=80&w=800&auto=format&fit=crop"},{"id":"fac-smp-3","name":"Laboratorium IPA Modern","description":"Fasilitas praktikum Fisika, Kimia, dan Biologi dengan peralatan uji standar nasional.","imageUrl":"https://images.unsplash.com/photo-1532094349884-543bc11b234d?q=80&w=800&auto=format&fit=crop"},{"id":"fac-smp-4","name":"Perpustakaan & Pojok Literasi Digital","description":"Koleksi ribuan buku referensi pelajaran, fiksi islami, ensiklopedia, dan e-book reader.","imageUrl":"https://images.unsplash.com/photo-1521587760476-6c12a4b040da?q=80&w=800&auto=format&fit=crop"},{"id":"fac-smp-5","name":"Lapangan Olahraga Multifungsi","description":"Lapangan serbaguna untuk Futsal, Bola Basket, Bola Voli, dan upacara bendera.","imageUrl":"https://images.unsplash.com/photo-1526676037777-05a232554f77?q=80&w=800&auto=format&fit=crop"}]}'::jsonb, true),
  ('smp.extracurricular', 'Profil SMP', 'Halaman ekstrakurikuler', '{"eyebrow":"Pengembangan minat & bakat","title":"Ekstrakurikuler SMP Al-Huda","description":"Wadah eksplorasi potensi kepemimpinan, olahraga, seni, sains, dan kebahasaan.","items":[{"id":"ex-1","name":"Pramuka Penggalang (Gugus Depan Al-Huda)","category":"keagamaan","schedule":"Jumat, 14.00 - 16.30 WIB","coach":"Kak Wahyu Pratama, S.Pd. & Kak Linda","description":"Membentuk karakter disiplin, kepemimpinan, kepedulian alam, dan ketangkasan.","imageUrl":"https://images.unsplash.com/photo-1577896851231-70ef18881754?q=80&w=600&auto=format&fit=crop"},{"id":"ex-2","name":"Seni Hadrah & Sholawat Banjari","category":"seni_budaya","schedule":"Sabtu, 15.30 - 17.30 WIB","coach":"Ustadz Ahmad Farhan","description":"Melatih olah vokal religius, tabuhan rebana banjari klasik dan kontemporer berprestasi.","imageUrl":"https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?q=80&w=600&auto=format&fit=crop"},{"id":"ex-3","name":"Futsal & Sepakbola Pelajar","category":"olahraga","schedule":"Selasa & Kamis, 15.30 - 17.00 WIB","coach":"Coach Dimas Saputra (Lisensi C AFC)","description":"Pembinaan fisik, taktik sepakbola, dan pembentukan tim kejuaraan antar sekolah.","imageUrl":"https://images.unsplash.com/photo-1526676037777-05a232554f77?q=80&w=600&auto=format&fit=crop"},{"id":"ex-4","name":"Klub Sains & Robotika Cilik","category":"akademik_it","schedule":"Rabu, 15.00 - 16.30 WIB","coach":"Agus Setiawan, S.Kom.","description":"Merakit robot berbasis Arduino, koding dasar Scratch, dan persiapan OSN.","imageUrl":"https://images.unsplash.com/photo-1531482615713-2afd69097998?q=80&w=600&auto=format&fit=crop"},{"id":"ex-5","name":"English & Arabic Conversation Club","category":"akademik_it","schedule":"Senin & Kamis, 15.30 - 16.30 WIB","coach":"Siti Rahmawati, S.Pd. & Ustadz Farid","description":"Melatih kemampuan public speaking, pidato 3 bahasa, dan drama bilingual.","imageUrl":"https://images.unsplash.com/photo-1524178232363-1fb2b075b655?q=80&w=600&auto=format&fit=crop"},{"id":"ex-6","name":"Seni Bela Diri Pagar Nusa & Tapak Suci","category":"olahraga","schedule":"Ahad Pagi, 06.30 - 08.30 WIB","coach":"Pendekar M. Sodiq","description":"Melestarikan pencak silat warisan ulama nusantara, ketahanan fisik, dan pertahanan diri.","imageUrl":"https://images.unsplash.com/photo-1555597673-b21d5c935865?q=80&w=600&auto=format&fit=crop"}]}'::jsonb, true),
  ('pondok.hero', 'Profil pesantren', 'Sambutan pesantren', '{"eyebrow":"Pesantren salafiyah & tahfidzul Qur’an","title":"Pondok Pesantren Al-Huda Tundungan","description":"Membina adab, menghidupkan tradisi keilmuan turots (kitab kuning), dan membimbing santri menghafal Al-Qur’an 30 Juz secara mutqin."}'::jsonb, true),
  ('pondok.history', 'Profil pesantren', 'Sejarah dan program pesantren', '{"title":"Sejarah Singkat Pondok Pesantren Al-Huda","subtitle":"Sejarah dan program pesantren","paragraphOne":"Pondok Pesantren Al-Huda didirikan sebagai benteng aqidah Ahlussunnah wal Jama’ah di wilayah Krian, Sidoarjo. Diprakarsai oleh para masyayikh untuk membimbing santri yang ingin memperdalam ilmu agama Islam serta menghafal Al-Qur’an.","paragraphTwo":"Dengan sistem sorogan, bandongan, dan talaqqi sanad, pesantren berkembang dengan sarana asrama mandiri serta integrasi waktu belajar dengan sekolah formal SMP Al-Huda.","statOne":"Tahfidz 30 Juz","statOneNote":"Sanad Muttashil","statTwo":"Madrasah Diniyah","statTwoNote":"Ula, Wustho, & Ulya","statThree":"24 Jam Pembinaan","statThreeNote":"Asrama Mandiri","statFour":"Kitab Kuning","statFourNote":"Fiqih, Nahwu, Hadits"}'::jsonb, true),
  ('pondok.vision', 'Profil pesantren', 'Visi dan misi pesantren', '{"visionTitle":"Visi Pondok Pesantren","missionTitle":"Misi Pondok Pesantren","vision":"Terwujudnya santri yang hafidz Al-Qur’an, mutafaqqih fiddin berhaluan Ahlussunnah wal Jama’ah An-Nahdliyyah, berakhlak karimah, serta siap mengabdi kepada umat dan bangsa.","missionOne":"Melaksanakan pembelajaran Al-Qur’an dengan metode tahsin bersanad dan tahfidz intensif.","missionTwo":"Mempertahankan kajian kitab kuning salaf melalui sorogan, wetonan, dan musyawarah bahtsul masail.","missionThree":"Menumbuhkan budaya riyadhah, sholat berjamaah lima waktu di masjid, dan qiyamul lail."}'::jsonb, true),
  ('pondok.programs', 'Profil pesantren', 'Program unggulan', '{"eyebrow":"Program pendidikan pesantren","title":"Dua Pilar Program Utama Santri","description":"Kombinasi intensif yang membimbing santri menghafal kalam ilahi dan memahami kaidah syariat secara mendalam.","cardOneBadge":"Program 01","cardOneTitle":"Tahfidzul Qur’an 30 Juz Bersanad","cardOneDescription":"Bimbingan tahsinul qira’ah dan setoran hafalan baru serta muroja’ah bersama para huffadz.","cardOneHighlights":[{"id":"tahfidz-1","text":"Target Hafalan: 10 Juz / Tahun untuk santri takhassus"},{"id":"tahfidz-2","text":"Ujian Tasmi’ Bil Ghoib sekali duduk (1 Juz, 5 Juz, 30 Juz)"},{"id":"tahfidz-3","text":"Ijazah Sanad Tahfidz bagi santri yang khatam mutqin"}],"cardOneFooter":"Program Mukim & Non-Mukim","cardTwoBadge":"Program 02","cardTwoTitle":"Madrasah Diniyah Salafiyah (Kajian Kitab Kuning)","cardTwoDescription":"Pendalaman kitab-kitab muktabarah dalam bidang gramatika Arab, fiqih Syafi’i, dan akhlak tasawuf.","cardTwoHighlights":[{"id":"diniyah-1","text":"Jenjang Diniyah: Ula (Dasar), Wustho (Menengah), Ulya (Lanjutan)"},{"id":"diniyah-2","text":"Latihan Bahtsul Masail & Musyawarah Fiqih Santri"},{"id":"diniyah-3","text":"Khotmil Kutub & Ijazahan Sanad Kitab setiap akhir tahun"}],"cardTwoFooter":"Kurikulum Pesantren Terpadu"}'::jsonb, true),
  ('pondok.cta', 'Profil pesantren', 'Ajakan menghubungi', '{"title":"Ingin mengenal lebih jauh Pesantren Al-Huda?","description":"Sekretariat siap membantu menjawab pertanyaan tentang kegiatan dan program pesantren.","action":"Hubungi sekretariat"}'::jsonb, true),
  ('layout.pondok-profile', 'Profil pesantren', 'Urutan bagian halaman profil', '{"items":[{"id":"pondok.hero","title":"Sambutan pesantren"},{"id":"pondok.history","title":"Sejarah dan program pesantren"},{"id":"pondok.vision","title":"Visi dan misi pesantren"},{"id":"pondok.programs","title":"Program unggulan"}]}'::jsonb, true),
  ('pondok.facilities', 'Profil pesantren', 'Halaman fasilitas pesantren', '{"eyebrow":"Sarana pesantren","title":"Fasilitas Asrama & Kompleks Pondok","description":"Masjid jami’, asrama santri putra dan putri terpisah, aula, dan lingkungan pesantren yang nyaman.","itemNote":"Bersih & Representatif","locationLabel":"Kompleks Pesantren","items":[{"id":"fac-pon-1","name":"Masjid Jami'' Al-Huda Tundungan","description":"Pusat spiritual komplek yayasan dengan kapasitas 1.200 jamaah untuk sholat 5 waktu berjamaah dan halaqah Al-Qur''an.","imageUrl":"https://images.unsplash.com/photo-1542810634-71277d95dcbb?q=80&w=800&auto=format&fit=crop"},{"id":"fac-pon-2","name":"Gedung Asrama Putra & Putri Terpisah","description":"Gedung asrama bertingkat dengan sirkulasi udara baik, lemari individu, kasur nyaman, dan pengawasan 24 jam oleh asatidz.","imageUrl":"https://images.unsplash.com/photo-1555854877-bab0e564b8d5?q=80&w=800&auto=format&fit=crop"},{"id":"fac-pon-3","name":"Dapur Umum Higienis & Ruang Makan Terpadu","description":"Penyediaan menu makanan santri 3x sehari yang bergizi, higienis, dan diawasi standar gizi.","imageUrl":"https://images.unsplash.com/photo-1556911220-e15b29be8c8f?q=80&w=800&auto=format&fit=crop"},{"id":"fac-pon-4","name":"Pos Kesehatan Pesantren (Poskestren)","description":"Pelayanan kesehatan pertama bagi santri bekerjasama dengan Puskesmas Krian dan RS Rujukan Sidoarjo.","imageUrl":"https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?q=80&w=800&auto=format&fit=crop"}]}'::jsonb, true),
  ('pondok.schedule', 'Profil pesantren', 'Jadwal harian santri', '{"eyebrow":"Rutinitas & kedisiplinan santri","title":"Jadwal Harian Santri 24 Jam","description":"Ritme kehidupan asrama yang mendidik santri mandiri, menghargai waktu, istiqomah beribadah, dan giat menuntut ilmu.","scheduleTitle":"Aktivitas Harian Santri Mukim","scheduleLabel":"Senin - Ahad Terstruktur","noteTitle":"Karakteristik Riyadhah & Kedisiplinan Al-Huda","note":"Santri dibiasakan menjaga wudhu, sholat berjamaah lima waktu di masjid, berpuasa sunnah, dan saling menghormati dengan adab.","items":[{"id":"sc-1","time":"03.30 - 04.15 WIB","activity":"Qiyamul Lail & Sholat Tahajud Mandiri","description":"Bangun pagi, bersuci, dan melaksanakan shalat sunnah malam di Masjid.","type":"ibadah"},{"id":"sc-2","time":"04.15 - 05.00 WIB","activity":"Sholat Subuh Berjamaah & Dzikir Pagi","description":"Sholat subuh berjamaah dipimpin Pengasuh dilanjutkan wirid Ratibul Haddad.","type":"ibadah"},{"id":"sc-3","time":"05.00 - 06.15 WIB","activity":"Halaqah Tahfidz & Setoran Hafalan Qur''an","description":"Setoran hafalan baru (ziyadah) dan pengulangan hafalan (muroja''ah) ke asatidz.","type":"tahfidz"},{"id":"sc-4","time":"06.15 - 07.00 WIB","activity":"Mandi Pagi, Sarapan Bersama & Persiapan Sekolah","description":"Makan pagi di dapur umum dan persiapan seragam sekolah formal.","type":"istirahat"},{"id":"sc-5","time":"07.00 - 13.00 WIB","activity":"KBM Sekolah Formal (SMP Al-Huda)","description":"Mengikuti pembelajaran kurikulum nasional di gedung sekolah SMP.","type":"formal"},{"id":"sc-6","time":"13.00 - 14.30 WIB","activity":"Sholat Dzuhur Berjamaah, Makan Siang & Qailulah","description":"Sholat dzuhur, makan siang bersama, dan istirahat sejenak.","type":"istirahat"},{"id":"sc-7","time":"14.30 - 15.30 WIB","activity":"Madrasah Diniyah (Kajian Kitab Kuning)","description":"Kajian nahwu-shorof, fiqih safinatun najah/fathul qorib, dan akhlaq.","type":"diniyah"},{"id":"sc-8","time":"15.30 - 16.30 WIB","activity":"Sholat Ashar Berjamaah & Olahraga Sore","description":"Sholat ashar berjamaah, dilanjutkan olahraga mandiri/ekstrakurikuler santri.","type":"ibadah"},{"id":"sc-9","time":"17.30 - 19.30 WIB","activity":"Sholat Maghrib, Muroja''ah Kubro & Sholat Isya''","description":"Membaca surat pilihan (Al-Waqi''ah & Yasin) dan tadarrus bersama.","type":"ibadah"},{"id":"sc-10","time":"19.30 - 21.00 WIB","activity":"Belajar Terbimbing & Muhadhoroh 3 Bahasa","description":"Pendampingan PR sekolah formal dan latihan pidato/khitobah mingguan.","type":"diniyah"},{"id":"sc-11","time":"21.00 - 22.00 WIB","activity":"Muroja''ah Santai & Cek Absensi Malam","description":"Pengecekan kamar santri oleh pengurus asrama dan persiapan tidur.","type":"istirahat"},{"id":"sc-12","time":"22.00 - 03.30 WIB","activity":"Istirahat Malam (Jam Wajib Tidur)","description":"Lampu utama asrama dipadamkan untuk menjaga kebugaran santri.","type":"istirahat"}]}'::jsonb, true),
  ('contact.hero', 'Kontak', 'Sambutan kontak', '{"eyebrow":"Pusat informasi & sekretariat","title":"Hubungi Yayasan Al-Huda Tundungan","description":"Kami siap melayani pertanyaan seputar kegiatan sekolah dan pesantren, kemitraan, kunjungan silaturahmi, dan informasi akademik."}'::jsonb, true),
